package br.com.mathinclui.auth.security;

import com.nimbusds.jose.jwk.source.ImmutableSecret; import com.nimbusds.jose.proc.SecurityContext; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.http.HttpMethod; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.oauth2.core.*; import org.springframework.security.oauth2.jose.jws.MacAlgorithm; import org.springframework.security.oauth2.jwt.*; import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationConverter; import org.springframework.security.web.SecurityFilterChain; import javax.crypto.SecretKey; import javax.crypto.spec.SecretKeySpec; import java.nio.charset.StandardCharsets; import java.security.*; import java.time.*; import java.util.List;
@Configuration
public class SecurityConfig {
    @Bean SecurityFilterChain securityFilterChain(HttpSecurity http,JwtAuthenticationConverter jwtAuthenticationConverter,JwtDecoder jwtDecoder)throws Exception{ http.csrf(csrf->csrf.disable()).sessionManagement(session->session.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(auth->auth.requestMatchers(HttpMethod.POST,"/api/v1/auth/professor/register","/api/v1/auth/professor/login","/api/v1/auth/professor/forgot-password","/api/v1/auth/professor/reset-password","/api/v1/auth/aluno/login","/api/v1/auth/refresh","/api/v1/auth/logout").permitAll().requestMatchers("/api/v1/system/info","/actuator/health","/actuator/info").permitAll().requestMatchers("/api/v1/auth/me").authenticated().requestMatchers("/api/v1/aluno/**").hasRole("ALUNO").requestMatchers("/api/v1/turmas/**","/api/v1/alunos/**","/api/v1/atividades/**","/api/v1/atribuicoes/**","/api/v1/dashboard/**").hasRole("PROFESSOR").anyRequest().authenticated()).oauth2ResourceServer(oauth->oauth.jwt(jwt->jwt.decoder(jwtDecoder).jwtAuthenticationConverter(jwtAuthenticationConverter))).httpBasic(httpBasic->httpBasic.disable()).formLogin(form->form.disable()); return http.build(); }
    @Bean PasswordEncoder passwordEncoder(){ return new BCryptPasswordEncoder(); }
    @Bean SecretKey jwtSecretKey(@Value("${app.security.jwt.secret}") String secret){ if(secret==null||secret.length()<24) throw new IllegalStateException("JWT secret must contain at least 24 characters"); try{ var digest=MessageDigest.getInstance("SHA-256").digest(secret.getBytes(StandardCharsets.UTF_8)); return new SecretKeySpec(digest,"HmacSHA256"); }catch(NoSuchAlgorithmException e){ throw new IllegalStateException("SHA-256 unavailable",e);} }
    @Bean JwtEncoder jwtEncoder(SecretKey key){ return new NimbusJwtEncoder(new ImmutableSecret<SecurityContext>(key)); }
    @Bean JwtDecoder jwtDecoder(SecretKey key){ var decoder=NimbusJwtDecoder.withSecretKey(key).macAlgorithm(MacAlgorithm.HS256).build(); OAuth2TokenValidator<Jwt> accessTokenValidator=jwt->{ if("access".equals(jwt.getClaimAsString("token_type"))) return OAuth2TokenValidatorResult.success(); return OAuth2TokenValidatorResult.failure(new OAuth2Error("invalid_token","Access token required",null));}; decoder.setJwtValidator(new DelegatingOAuth2TokenValidator<>(JwtValidators.createDefaultWithIssuer("mathinclui"),accessTokenValidator)); return decoder; }
    @Bean JwtAuthenticationConverter jwtAuthenticationConverter(){ var converter=new JwtAuthenticationConverter(); converter.setJwtGrantedAuthoritiesConverter(jwt->{ var role=jwt.getClaimAsString("role"); return role==null?List.of():List.of(new SimpleGrantedAuthority(role));}); return converter; }
    @Bean Clock clock(){ return Clock.systemUTC(); }
    @Bean LoginAttemptTracker loginAttemptTracker(@Value("${app.security.login.max-attempts:5}") int maxAttempts,@Value("${app.security.login.block-seconds:900}") long blockSeconds,Clock clock){ return new LoginAttemptTracker(maxAttempts,Duration.ofSeconds(blockSeconds),clock); }
}
